import{_ as s,C as n,o,c as r,ag as e,E as l}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"Mass Payout Management","description":"","frontmatter":{},"headers":[],"relativePath":"payments/mass-payout-management.md","filePath":"payments/mass-payout-management.md","lastUpdated":1786121967000}'),i={name:"payments/mass-payout-management.md"};function m(p,a,u,c,y,d){const t=n("ImagePopup");return o(),r("div",null,[a[0]||(a[0]=e('<h1 id="mass-payout-management" tabindex="-1">Mass Payout Management <a class="header-anchor" href="#mass-payout-management" aria-label="Permalink to &quot;Mass Payout Management&quot;">​</a></h1><p>When a marketplace has many sellers with pending earnings, paying them one at a time is slow. <strong>Mass payout</strong> lets the admin settle multiple payable orders — across one or many sellers — in a single action, from the same Seller Payout Management screen.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How mass payout relates to individual payments</li><li>How to pay several orders at once</li><li>How to target a payout run with filters</li></ul></div><h2 id="where-mass-payout-lives" tabindex="-1">Where mass payout lives <a class="header-anchor" href="#where-mass-payout-lives" aria-label="Permalink to &quot;Where mass payout lives&quot;">​</a></h2><p>Mass payout is the <strong>bulk action</strong> on the same <strong>Seller Payout Management</strong> screen used for individual payments — <strong>Marketplace → Sales → Payment Requests</strong>. See <a href="/payments/payment-management#paying-sellers-admin">Payment Management</a> for the screen&#39;s summary cards and columns; this page focuses on settling many orders in one go.</p><p>Before selecting, use the <strong>filters</strong> (seller, customer, amount, status, or date) to narrow the list down to exactly the orders you want to clear in this run.</p>',6)),l(t,{src:"/images/mass-payout-management/payout-management.png",alt:"Seller Payout Management with payable orders"}),a[1]||(a[1]=e('<h2 id="paying-in-bulk" tabindex="-1">Paying in bulk <a class="header-anchor" href="#paying-in-bulk" aria-label="Permalink to &quot;Paying in bulk&quot;">​</a></h2><p>Select the payable orders you want to settle with the row checkboxes, then use the bulk <strong>Pay Now</strong> action to pay them together. Each order is settled for its full remaining amount and stamped with a system comment, exactly as an individual <a href="/payments/payment-management">payment</a> is — just processed as a batch — and each records a <a href="/payments/payment-management#transactions">transaction</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the summary cards and filters to target a payout run — for example, clear every fully-invoiced order for the month in one pass, rather than chasing sellers individually.</p></div>',3))])}const _=s(i,[["render",m]]);export{g as __pageData,_ as default};
